const raw = ($json.candidates && $json.candidates[0] && $json.candidates[0].content &&
  $json.candidates[0].content.parts && $json.candidates[0].content.parts[0] &&
  $json.candidates[0].content.parts[0].text) || '';

const fallback = {
  severity: 'unclassified',
  category: 'unknown',
  expected_behavior: '',
  actual_behavior: '',
  first_divergence_stage: 'unknown',
  first_divergence_node: 'unknown - analyzer response could not be parsed',
  root_cause_explanation: 'The root cause analyzer did not return parseable JSON. Raw model output is attached for manual review.',
  evidence: [],
  downstream_impact: '',
  recommended_investigation: 'Re-run analysis; if this persists, inspect the raw_llm_response field.',
  recommended_fix: '',
  confidence: 0,
};

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = Object.assign({}, fallback, { raw_text: raw });
}

const result = Object.assign({}, fallback, parsed);
result.confidence = Number(result.confidence);
if (!Number.isFinite(result.confidence)) result.confidence = 0;

return [{ json: { result, raw_response: $json } }];
